(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.33)*11;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.17)*7 + Math.sin((x+y)*0.009-t*0.14)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1, 0.8],
    [320+Math.cos(t*0.5)*105, 160+Math.sin(t*0.7)*55, 0.095, 1.8, 1.0],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.055, 2.4, 0.6],
    [120+Math.cos(t*0.8+1)*85, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6, 1.1],
    [360+Math.sin(t*0.4+4)*95, 60+Math.cos(t*0.9+2)*75, 0.065, 2.7, 0.7],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.085, 2.0, 0.9],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.45+2)*50, 0.13, 1.4, 1.2],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.65+4)*45, 0.07, 2.8, 0.5],
    [200+Math.sin(t*0.25+6)*120, 220+Math.cos(t*0.38)*70, 0.1, 1.9, 0.85],
    [300+Math.cos(t*0.48+3)*100, 100+Math.sin(t*0.58+2)*80, 0.06, 2.5, 0.75]
  ];
  let aS=0, iS=0, pS=0, n=10;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    pS += Math.sin(d*f*0.4-t*sp*0.3+Math.atan2(sy-sY,sx-sX)*2)*w*0.5;
  }
  const act=aS/n, inh=iS/n, phase=pS/n;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.85)+Math.sin(sx*0.028-sy*0.038+t*1.15))/2
    + Math.sin((sx+sy)*0.11+t*2.6)*0.2 + Math.sin((sx-sy)*0.095-t*2.1)*0.2
    + Math.sin(sx*0.06+t*1.8)*Math.sin(sy*0.06-t*1.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
