    + Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const ripple = Math.sin(dist*0.12-t*3)*Math.exp(-dist*0.005)*0.3;
  let vField = 0;
  for (let i=0; i<3; i++) {
    const a = t*0.4+i*2.094;
    vField += Math.sin((sx-240-Math.cos(a)*100)*0.08)*Math.sin((sy-120-Math.sin(a)*80)*0.08);
  }
  vField *= 0.2;
  const rd = act - inh*0.65 + bg*0.25 + spiral + phase*0.15 + ripple + vField;
  const reaction = Math.tanh(rd*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.5+Math.sin(sx*0.07-t*0.8)*Math.cos(sy*0.07+t*0.6)*0.3)*1.4)*0.25;
  const fiber = Math.sin(Math.sqrt((Math.sin(sx*0.05+t)*50)**2+(Math.cos(sy*0.04-t*0.7)*50)**2)*0.15)*0.15;
  const blend = reaction*0.6 + cell*0.2 + fiber*0.1 + spiral*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,95],[12,85,120],[18,130,135],
    [80,165,120],[170,185,80],[220,190,60],[230,140,55],
    [215,90,60],[180,55,70],[120,30,65],[55,18,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const shimmer=Math.sin(t*4+sx*0.1+sy*0.1)*0.03+1;
  const g=(pal[i][1]+(pal[i+1][1]-pal[i][1])*f);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*shimmer)|0,
    Math.min(255,g*lum*edge*shimmer+(Math.abs(reaction)>0.5?8:0))|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*shimmer)|0
  ];
}
